<?php
namespace App\Interfaces\Http\Controllers\Api\V1\BrokerOperations;use App\Application\Audit\AuditWriter;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class BrokerOperationsController{
public function createBordereau(Request$r,AuditWriter$audit){if(is_string($r->input('type')))$r->merge(['type'=>\App\Application\FinancialDistribution\ReinsuranceReference::bordereauType($r->input('type'))]);$d=$r->validate(['carrier_id'=>'required|uuid|exists:carriers,id','type'=>'required|in:PREMIUM,CLAIM,ENDORSEMENT,CANCELLATION','period_start'=>'required|date','period_end'=>'required|date|after_or_equal:period_start','policy_ids'=>'required|array|min:1|max:5000','policy_ids.*'=>'uuid|exists:policies,id']);$tenant=app(\App\Domain\Tenancy\TenantContext::class)->id();$policies=DB::table('policies')->where('tenant_id',$tenant)->where('carrier_id',$d['carrier_id'])->whereIn('id',$d['policy_ids'])->get();abort_unless($policies->count()===count(array_unique($d['policy_ids'])),422,'Every policy must belong to the broker tenant and carrier.');$id=(string)Str::uuid();$number='BOR-'.now()->format('Ym').'-'.strtoupper(Str::random(8));$gross=(int)$policies->sum('premium_minor');$commission=(int)DB::table('commission_accruals')->whereIn('policy_id',$policies->pluck('id'))->sum('amount_minor');DB::transaction(function()use($d,$tenant,$policies,$id,$number,$gross,$commission,$r,$audit){DB::table('bordereaux')->insert(['id'=>$id,'tenant_id'=>$tenant,'carrier_id'=>$d['carrier_id'],'type'=>$d['type'],'bordereau_number'=>$number,'period_start'=>$d['period_start'],'period_end'=>$d['period_end'],'status'=>'DRAFT','item_count'=>$policies->count(),'gross_premium_minor'=>$gross,'commission_minor'=>$commission,'currency'=>'XAF','prepared_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($policies as$p)DB::table('bordereau_items')->insert(['id'=>(string)Str::uuid(),'bordereau_id'=>$id,'policy_id'=>$p->id,'transaction_type'=>$d['type'],'premium_minor'=>$p->premium_minor,'commission_minor'=>(int)DB::table('commission_accruals')->where('policy_id',$p->id)->sum('amount_minor'),'currency'=>$p->currency,'effective_at'=>$p->issued_at??$p->created_at,'created_at'=>now(),'updated_at'=>now()]);$audit->record('bordereau.created','bordereau',$id,['number'=>$number,'items'=>$policies->count()]);});return response()->json(['data'=>['id'=>$id,'bordereau_number'=>$number,'gross_premium_minor'=>$gross,'commission_minor'=>$commission]],201);}
public function submitBordereau(Request$r,string$bordereau,AuditWriter$audit){$d=$r->validate(['notes'=>'required|string|min:20|max:2000']);$row=DB::table('bordereaux')->where('tenant_id',app(\App\Domain\Tenancy\TenantContext::class)->id())->where(['id'=>$bordereau,'status'=>'APPROVED'])->first();abort_unless($row,409,'Only an approved bordereau can be submitted.');abort_if($row->prepared_by===$r->user()->id,403,'The preparer of a bordereau cannot submit it.');DB::table('bordereaux')->where('id',$bordereau)->update(['status'=>'SUBMITTED','submitted_by'=>$r->user()->id,'submitted_at'=>now(),'updated_at'=>now()]);$audit->record('bordereau.submitted','bordereau',$bordereau,['number'=>$row->bordereau_number]);return response()->json(['data'=>['id'=>$bordereau,'status'=>'SUBMITTED']]);}
public function seedRenewals(Request$r,AuditWriter$audit){$d=$r->validate(['days_ahead'=>'required|integer|min:1|max:180']);$tenant=app(\App\Domain\Tenancy\TenantContext::class)->id();$policies=DB::table('policies')->where('tenant_id',$tenant)->whereIn('status',['ACTIVE','EXPIRING'])->whereBetween('coverage_ends_at',[now(),now()->addDays($d['days_ahead'])])->get();$created=0;foreach($policies as$p)$created+=DB::table('renewal_work_items')->insertOrIgnore(['id'=>(string)Str::uuid(),'tenant_id'=>$tenant,'policy_id'=>$p->id,'renewal_due_on'=>substr($p->coverage_ends_at,0,10),'status'=>'DUE','contact_attempts'=>0,'created_at'=>now(),'updated_at'=>now()]);$audit->record('renewal.work_items.seeded','tenant',$tenant,['created'=>$created]);return response()->json(['data'=>['created'=>$created]]);}}
